const BoxSelector = React.memo(({ isSelecting, start, end }: { isSelecting: boolean, start: {x:number, y:number}, end: {x:number, y:number} }) => {
    if (!isSelecting) return null;
    const left = Math.min(start.x, end.x);
    const top = Math.min(start.y, end.y);
    const width = Math.abs(end.x - start.x);
    const height = Math.abs(end.y - start.y);

    return (
        <Html fullscreen style={{ pointerEvents: 'none', zIndex: 100, transform: 'none', top: 0, left: 0 }}>
             <div style={{
                 position: 'absolute',
                 left, top, width, height,
                 backgroundColor: 'rgba(59, 130, 246, 0.2)',
                 border: '1px solid #3b82f6',
             }} />
        </Html>
    );
});

const useBoxSelection = () => {
    const { tool, selectShapes, shapes, layers, selectShape, deselectAll } = useApp();
    const { gl, camera } = useThree();
    const [selectionState, setSelectionState] = useState<{ start: {x:number, y:number}, end: {x:number, y:number}, isSelecting: boolean }>({
        start: {x:0, y:0}, end: {x:0, y:0}, isSelecting: false
    });

    // Handle global pointer moves and ups
    useEffect(() => {
        if (!selectionState.isSelecting) return;

        const onPointerMove = (e: PointerEvent) => {
            const rect = gl.domElement.getBoundingClientRect();
            setSelectionState(prev => ({
                ...prev,
                end: { x: e.clientX - rect.left, y: e.clientY - rect.top }
            }));
        };

        const onPointerUp = (e: PointerEvent) => {
            // Calculate selection
            const rect = gl.domElement.getBoundingClientRect();
            const endX = e.clientX - rect.left;
            const endY = e.clientY - rect.top;

            const startX = selectionState.start.x;
            const startY = selectionState.start.y;

            // Define box (min/max)
            const minX = Math.min(startX, endX);
            const maxX = Math.max(startX, endX);
            const minY = Math.min(startY, endY);
            const maxY = Math.max(startY, endY);

            // Small drag threshold to avoid accidental selections on clicks
            if (Math.abs(maxX - minX) > 5 && Math.abs(maxY - minY) > 5) {
                const idsToSelect: string[] = [];

                shapes.forEach(shape => {
                    const layer = layers.find(l => l.id === shape.layerId);
                    if (layer && !layer.visible) return;

                    // Project object center to screen space
                    const pos = new THREE.Vector3(...shape.position);
                    pos.project(camera); // -1 to 1

                    // Convert to canvas coords
                    const x = (pos.x * 0.5 + 0.5) * rect.width;
                    const y = (-(pos.y * 0.5) + 0.5) * rect.height;

                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
                        idsToSelect.push(shape.id);
                    }
                });

                if (e.ctrlKey || e.metaKey || e.shiftKey) {
                   // Append mode
                   selectShapes(idsToSelect); 
                } else {
                   selectShapes(idsToSelect);
                }
            } else {
                // Treated as a click - usually deselect all if on background, handled by onPointerMissed?
                // But onPointerMissed fires on click. If we dragged a tiny bit, maybe do nothing.
                if (tool === ToolType.SELECT && !e.ctrlKey) {
                    deselectAll();
                }
            }

            setSelectionState(prev => ({ ...prev, isSelecting: false }));
        };

        window.addEventListener('pointermove', onPointerMove);
        window.addEventListener('pointerup', onPointerUp);

        return () => {
            window.removeEventListener('pointermove', onPointerMove);
            window.removeEventListener('pointerup', onPointerUp);
        };
    }, [selectionState.isSelecting, gl, camera, shapes, layers, selectShapes, deselectAll, tool]);

    const onPointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;

        // Ensure we use Native Event coordinates for consistency with pointermove
        const nE = e.nativeEvent;
        const rect = gl.domElement.getBoundingClientRect();
        const x = nE.clientX - rect.left;
        const y = nE.clientY - rect.top;

        setSelectionState({
            start: { x, y },
            end: { x, y },
            isSelecting: true
        });

    }, [tool, gl]);

    return { 
        boxState: selectionState,
        onPointerDown,
        BoxSelectorComponent: <BoxSelector isSelecting={selectionState.isSelecting} start={selectionState.start} end={selectionState.end} />
    };
};

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Edges, Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Ray distance threshold
const ALIGN_THRESHOLD = 0.3;
const EPSILON = 1e-4;

// --- Helper: Get Local Basis Vectors from Normal ---
const getLocalBasis = (normal: THREE.Vector3) => {
    const n = normal.clone().normalize();
    let up = new THREE.Vector3(0, 1, 0);
    if (Math.abs(n.dot(up)) > 0.99) up.set(0, 0, 1);

    const right = new THREE.Vector3().crossVectors(n, up).normalize();
    const top = new THREE.Vector3().crossVectors(right, n).normalize(); 

    return { right, top, normal: n };
};

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const v = new THREE.Vector3(localP.x, 0, localP.z);
    v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
    const euler = new THREE.Euler(...shape.rotation);
    v.applyEuler(euler);
    v.add(new THREE.Vector3(...shape.position));
    return v;
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;

    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    // Position
    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    // Rotate
    const euler = new THREE.Euler(...shape.rotation);
    const quat = new THREE.Quaternion().setFromEuler(euler);

    const left = new THREE.Vector3(-scaledHalfLen, 0, 0).applyQuaternion(quat);
    const right = new THREE.Vector3(scaledHalfLen, 0, 0).applyQuaternion(quat);

    return [pos.clone().add(left), pos.clone().add(right)];
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    ray: THREE.Ray,
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    let fallbackSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        let normal = new THREE.Vector3(0, 1, 0);
        if (intersectedObject.face) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
            normal = intersectedObject.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        }

        fallbackSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id,
            normal
        };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity,
            normal: new THREE.Vector3(0, 1, 0)
        };
    }

    let bestVertexSnap: SnapResult | null = null;
    let minVertexDist = threshold;

    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ray.distanceToPoint(ptVec);
        if (dist < threshold * 1.5) {
            bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist, normal: new THREE.Vector3(0,1,0) };
            minVertexDist = dist;
        }
    }

    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 const edgeVec = new THREE.Vector3().subVectors(endpoints[1], endpoints[0]).normalize();
                 for(const ep of endpoints) {
                     const dist = ray.distanceToPoint(ep);
                     if (dist < minVertexDist) {
                         bestVertexSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id, normal: edgeVec };
                         minVertexDist = dist;
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = ray.distanceToPoint(worldPt);

            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = transformPoint(shape.points[i], { ...shape, position: [shape.position[0], shape.position[1] + currentH, shape.position[2]] });
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                    minVertexDist = dist;
                }
            }
        }
    }

    if (bestVertexSnap) return bestVertexSnap;
    return fallbackSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return (
        <group renderOrder={9999}>
            {lines.map((line) => (
                <SimpleLine 
                    key={line.id} 
                    points={[line.points[0], line.points[1]]} 
                    color="#a855f7" 
                    dashed 
                    lineWidth={1} 
                    depthTest={false} 
                    opacity={0.8} 
                />
            ))}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue } = useApp();

    if (!shape.points || shape.points.length < 3) return null;

    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
    const p3 = new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);

    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);

    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);

    const color = isSelected ? '#3b82f6' : '#333';
    const length = p1.distanceTo(p2);

    return (
        <group onClick={(e) => { e.stopPropagation(); onSelect(e); }}>
            <SimpleLine points={[dimStart, dimEnd]} color={color} />
            <SimpleLine points={[p1, dimStart]} color="#999" dashed />
            <SimpleLine points={[p2, dimEnd]} color="#999" dashed />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} /></mesh>
            <Billboard position={[midPoint.x, midPoint.y + 0.1, midPoint.z]}>
                <Text fontSize={0.25} color={color} anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#ffffff" backgroundColor="#ffffff80" padding={0.05}>
                    {formatValue(length)}
                </Text>
            </Billboard>
        </group>
    );
};

const BoxSelector = React.memo(({ isSelecting, start, end }: { isSelecting: boolean, start: {x:number, y:number}, end: {x:number, y:number} }) => {
    if (!isSelecting) return null;
    const left = Math.min(start.x, end.x);
    const top = Math.min(start.y, end.y);
    const width = Math.abs(end.x - start.x);
    const height = Math.abs(end.y - start.y);

    return (
        <Html fullscreen style={{ pointerEvents: 'none', zIndex: 100, transform: 'none', top: 0, left: 0 }}>
             <div style={{
                 position: 'absolute', left, top, width, height,
                 backgroundColor: 'rgba(59, 130, 246, 0.2)', border: '1px solid #3b82f6',
             }} />
        </Html>
    );
});

const useBoxSelection = () => {
    const { tool, selectShapes, shapes, layers, deselectAll } = useApp();
    const { gl, camera } = useThree();
    const [selectionState, setSelectionState] = useState<{ start: {x:number, y:number}, end: {x:number, y:number}, isSelecting: boolean }>({
        start: {x:0, y:0}, end: {x:0, y:0}, isSelecting: false
    });

    useEffect(() => {
        if (!selectionState.isSelecting) return;
        const onPointerMove = (e: PointerEvent) => {
            const rect = gl.domElement.getBoundingClientRect();
            setSelectionState(prev => ({ ...prev, end: { x: e.clientX - rect.left, y: e.clientY - rect.top } }));
        };
        const onPointerUp = (e: PointerEvent) => {
            const rect = gl.domElement.getBoundingClientRect();
            const endX = e.clientX - rect.left;
            const endY = e.clientY - rect.top;
            const startX = selectionState.start.x;
            const startY = selectionState.start.y;
            const minX = Math.min(startX, endX);
            const maxX = Math.max(startX, endX);
            const minY = Math.min(startY, endY);
            const maxY = Math.max(startY, endY);

            if (Math.abs(maxX - minX) > 5 && Math.abs(maxY - minY) > 5) {
                const idsToSelect: string[] = [];
                shapes.forEach(shape => {
                    const layer = layers.find(l => l.id === shape.layerId);
                    if (layer && !layer.visible) return;
                    const pos = new THREE.Vector3(...shape.position);
                    pos.project(camera);
                    const x = (pos.x * 0.5 + 0.5) * rect.width;
                    const y = (-(pos.y * 0.5) + 0.5) * rect.height;
                    if (x >= minX && x <= maxX && y >= minY && y <= maxY) idsToSelect.push(shape.id);
                });
                selectShapes(idsToSelect);
            } else {
                if (tool === ToolType.SELECT && !e.ctrlKey) deselectAll();
            }
            setSelectionState(prev => ({ ...prev, isSelecting: false }));
        };
        window.addEventListener('pointermove', onPointerMove);
        window.addEventListener('pointerup', onPointerUp);
        return () => {
            window.removeEventListener('pointermove', onPointerMove);
            window.removeEventListener('pointerup', onPointerUp);
        };
    }, [selectionState.isSelecting, gl, camera, shapes, layers, selectShapes, deselectAll, tool]);

    const onPointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        const nE = e.nativeEvent;
        const rect = gl.domElement.getBoundingClientRect();
        setSelectionState({ start: { x: nE.clientX - rect.left, y: nE.clientY - rect.top }, end: { x: nE.clientX - rect.left, y: nE.clientY - rect.top }, isSelecting: true });
    }, [tool, gl]);

    return { boxState: selectionState, onPointerDown, BoxSelectorComponent: <BoxSelector isSelecting={selectionState.isSelecting} start={selectionState.start} end={selectionState.end} /> };
};

const ShapeRenderer: React.FC<ShapeRendererProps> = ({ shape, isSelected, onSelect }) => {
    const meshRef = useRef<THREE.Mesh>(null);
    const groupRef = useRef<THREE.Group>(null);

    if (shape.type === 'dimension') {
        return <DimensionShape shape={shape} isSelected={isSelected} onSelect={onSelect} />;
    }

    const threeShape = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const height = shape.height;
    const is3D = height > 0.001;

    const geometry = useMemo(() => {
        if (is3D) {
            return new THREE.ExtrudeGeometry(threeShape, { depth: height, bevelEnabled: false });
        } else {
            return new THREE.ShapeGeometry(threeShape);
        }
    }, [threeShape, height, is3D]);

    return (
        <group 
            ref={groupRef}
            position={shape.position} 
            rotation={shape.rotation} 
            scale={shape.scale}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => { e.stopPropagation(); onSelect(e); }}
        >
             <mesh ref={meshRef} geometry={geometry} rotation={[Math.PI / 2, 0, 0]}>
                <meshStandardMaterial color={shape.color} transparent opacity={0.9} />
                {isSelected && <Edges color={HIGHLIGHT_COLOR} threshold={15} />}
            </mesh>
        </group>
    );
};

const SceneContent: React.FC = () => {
    const { shapes, selectedIds, selectShape, guideLines } = useApp();
    const { boxState, onPointerDown, BoxSelectorComponent } = useBoxSelection();

    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
            <Grid infiniteGrid fadeDistance={50} sectionSize={1} cellSize={0.5} sectionColor="#94a3b8" cellColor="#cbd5e1" />
            <GuideLinesRenderer lines={guideLines} />

            <OrbitControls makeDefault enabled={!boxState.isSelecting} />

            <group onPointerDown={onPointerDown} onPointerMissed={() => selectShape('')}>
                {shapes.map(shape => (
                    <ShapeRenderer 
                        key={shape.id} 
                        shape={shape} 
                        isSelected={selectedIds.includes(shape.id)} 
                        onSelect={(e) => selectShape(shape.id, e.nativeEvent.shiftKey || e.nativeEvent.ctrlKey)}
                    />
                ))}
            </group>

            {BoxSelectorComponent}
        </>
    );
};

const Viewport: React.FC = () => {
  const { currentView } = useApp();

  return (
    <div className="w-full h-full relative bg-slate-50">
      <Canvas shadows camera={{ position: [8, 8, 8], fov: 45 }}>
